<script setup lang="ts">
import {ref,onMounted} from 'vue';const props=defineProps<{csrf:string}>();const data=ref<any>(null),error=ref(window.portal.error||window.portal.validationErrors.join(' ')),busy=ref(false),form=ref({name:'',password:'',password_confirmation:''});const path=location.pathname;
onMounted(async()=>{try{const r=await fetch(path+'/details',{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.message);data.value=d;form.value.name=d.name||'';}catch(e){error.value=(e as Error).message;}});
async function accept(){busy.value=true;error.value='';try{const r=await fetch(path,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf},body:JSON.stringify(data.value.existing?{}:form.value)});const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' '):d.message);location.assign(d.redirect_url);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><section class="admin-content"><h1>Welcome to Judibas</h1><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><div v-if="data"><p>Invitation for <strong>{{data.email}}</strong></p><p>Products: {{data.products.join(', ')}}</p><p v-if="data.companies.length">Companies: {{data.companies.join(', ')}}</p>
<form v-if="data.existing&&!data.can_accept" class="settings-form" action="/login" method="post"><p>Sign in with your existing password to add this access. Your account and password stay the same.</p><input type="hidden" name="_token" :value="csrf"><label>Email<input type="email" name="email" :value="data.email" readonly required autocomplete="username"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button class="button primary">Sign in to continue</button></form>
<form v-else class="settings-form" @submit.prevent="accept"><template v-if="!data.existing"><label>Name<input v-model="form.name" maxlength="100" required></label><label>Password<input type="password" v-model="form.password" minlength="12" required autocomplete="new-password"></label><label>Confirm password<input type="password" v-model="form.password_confirmation" minlength="12" required autocomplete="new-password"></label></template><p v-else>Accepting adds your assigned access while preserving your current products and password.</p><button class="button primary" :disabled="busy">{{busy?'Accepting?':'Accept invitation'}}</button></form></div></section></template>
